  <script>
    function calculate_pagination(total_items, items_per_page, current_page) {
      // Validate inputs
      if (total_items < 0 || items_per_page <= 0 || current_page < 1) {
        return {
          total_pages: 0,
          current_page: 1,
          has_next: false,
          has_prev: false
        };
      }

      // Calculate total pages, rounding up
      const total_pages = Math.ceil(total_items / items_per_page);

      // Clamp current page to valid range
      let clamped_page = Math.min(current_page, total_pages);
      if (current_page < 1) {
        clamped_page = 1;
      }

      return {
        total_pages,
        current_page: clamped_page,
        has_next: clamped_page < total_pages,
        has_prev: clamped_page > 1
      };
    }

    // Test cases
    console.log(calculate_pagination(25, 5, 1)); // {total_pages: 5, current_page: 1, has_next: true, has_prev: false}
    console.log(calculate_pagination(25, 5, 6)); // {total_pages: 5, current_page: 5, has_next: false, has_prev: true}
    console.log(calculate_pagination(25, 5, 0)); // {total_pages: 5, current_page: 1, has_next: true, has_prev: false}
    console.log(calculate_pagination(25, 5, -1)); // {total_pages: 5, current_page: 1, has_next: true, has_prev: false}
  </script>
