from collections import defaultdict, deque

def topological_sort(tasks, dependencies):
    # Build adjacency list and in-degree count
    graph = defaultdict(set)
    in_degree = {task: 0 for task in tasks}

    for dep, task in dependencies:
        graph[dep].add(task)
        in_degree[task] += 1

    # Find all nodes with zero in-degree (no dependencies)
    queue = deque()
    for task, count in in_degree.items():
        if count == 0:
            queue.append(task)

    result = []
    while queue:
        task = queue.popleft()
        result.append(task)

        # Remove task from all its dependent tasks
        for dependent in graph[task]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                queue.append(dependent)

        # Remove task from graph
        del graph[task]

    # If we haven't processed all tasks, there's a cycle
    if len(result) != len(tasks):
        return None

    return result

