from collections import deque

def is_bipartite(graph):
    """
    Check if an undirected graph is bipartite using BFS coloring.

    Args:
        graph: Dictionary where keys are nodes and values are lists of adjacent nodes

    Returns:
        bool: True if bipartite, False otherwise
    """
    if not graph:
        return True

    # Color array: -1 means unvisited, 0 and 1 are the two colors
    color = {}

    for node in graph:
        if node not in color:
            # Start BFS from this unvisited node
            queue = deque([node])
            color[node] = 0

            while queue:
                current = queue.popleft()

                for neighbor in graph[current]:
                    if neighbor not in color:
                        color[neighbor] = 1 - color[current]  # Alternate color
                        queue.append(neighbor)
                    elif color[neighbor] == color[current]:
                        # Adjacent nodes have same color -> odd cycle exists
                        return False

    return True

