import { Queue } from './data-structures';

/**
 * Performs a Breadth-First Search (BFS) on an unweighted undirected graph.
 *
 * @param graph - Adjacency list representation of the graph. Key is node ID, value is array of connected node IDs.
 * @param startNode - Starting node ID for BFS traversal.
 * @returns Array of nodes in the order they are visited.
 */
export function bfsGraph<T extends number | string>(
  graph: Record<T, T[]>,
  startNode: T
): T[] {
  if (!graph[startNode] || graph[startNode].length === 0) {
    return [];
  }

  const visited = new Set<T>();
  const result: T[] = [];
  const queue = new Queue<T>();

  queue.enqueue(startNode);
  visited.add(startNode);

  while (!queue.isEmpty()) {
    const current = queue.dequeue()!;
    result.push(current);

    for (const neighbor of graph[current]) {
      if (!visited.has(neighbor)) {
        visited.add(neighbor);
        queue.enqueue(neighbor);
      }
    }
  }

  return result;
}

