from collections import deque

def simulate_rw_lock(ops):
    # State: readers_count, writer_in_progress, writer_blocked_reads, writer_blocked_writes
    # writer_blocked_reads is a deque of read operations that are waiting for the writer
    # writer_blocked_writes is a deque of write operations that are waiting for the writer
    state = {
        'readers_count': 0,
        'writer_in_progress': False,
        'writer_blocked_reads': deque(),
        'writer_blocked_writes': deque()
    }
    results = []

    for op in ops:
        if op == 'read_acquire':
            if state['writer_in_progress']:
                state['writer_blocked_reads'].append(op)
                results.append(False)
            else:
                state['readers_count'] += 1
                results.append(True)
        elif op == 'read_release':
            if state['readers_count'] > 0:
                state['readers_count'] -= 1
                results.append(True)
            else:
                results.append(False)
        elif op == 'write_acquire':
            if state['writer_in_progress']:
                state['writer_blocked_writes'].append(op)
                results.append(False)
            else:
                state['writer_in_progress'] = True
                results.append(True)
        elif op == 'write_release':
            if state['writer_in_progress']:
                state['writer_in_progress'] = False
                # Unblock all waiting reads first
                while state['writer_blocked_reads']:
                    next_read = state['writer_blocked_reads'].popleft()
                    if state['writer_in_progress']:
                        state['writer_blocked_reads'].append(next_read)
                    else:
                        state['readers_count'] += 1
                        results.append(True)
                # Unblock all waiting writes
                while state['writer_blocked_writes']:
                    next_write = state['writer_blocked_writes'].popleft()
                    results.append(True)
            else:
                results.append(False)

    return results

