def longest_increasing_subsequence_count(nums):
    n = len(nums)
    if n == 0:
        return (0, 1)

    # dp[i] = (length, count) for LIS ending at index i
    dp = [(1, 1)] * n

    for i in range(1, n):
        for j in range(i):
            if nums[j] < nums[i]:
                new_len = dp[j][0] + 1
                if new_len > dp[i][0]:
                    dp[i] = (new_len, dp[j][1])
                elif new_len == dp[i][0]:
