def wildcard_match(text: str, pattern: str) -> bool:
    """
    Match entire string against pattern with:
    ? - matches exactly one character
    * - matches any sequence of characters (including empty)
    """
    # Base cases
    if not text:
        return pattern == ""

    if not pattern:
        return False

    # Current characters
    first_text_char = text[0]
    first_pattern_char = pattern[0]

    # If pattern starts with *, match anything from text
    if first_pattern_char == '*':
        # * can match empty string (skip it) OR match one char and recurse
        return wildcard_match(text, pattern[1:]) or \
               wildcard_match(text[1:], pattern)

    # If pattern starts with ?, match exactly one char
    if first_pattern_char == '?':
        return wildcard_match(text[1:], pattern[1:])

    # Otherwise characters must match exactly
    if first_text_char == first_pattern_char:
        return wildcard_match(text[1:], pattern[1:])

    return False

