from collections import deque

def strongly_connected_components(graph: dict[int, set[int]]) -> list[set[int]]:
    """
    Find all strongly connected components (SCCs) in a directed graph using Kosaraju's
    two-pass DFS. Returns a list of sets, each set being one SCC.
    """
    nodes = set(graph.keys())
    visited = set()
    stack = deque()
    sccs = []

    def dfs1(node):
        visited.add(node)
        for neighbor in graph.get(node, set()):
            if neighbor not in visited:
                dfs1(neighbor)
        stack.append(node)

    # First pass: DFS on original graph to fill stack with nodes in order of finishing time.
    for node in nodes:
        if node not in visited:
            dfs1(node)

    # Second pass: DFS on transpose graph in reverse stack order.
    transpose = {node: set() for node in nodes}
    for u in graph:
        for v in graph[u]:
            transpose[v].add(u)

    def dfs2(node, component):
        component.add(node)
        visited.add(node)
        for neighbor in transpose.get(node, set()):
            if neighbor not in visited:
                dfs2(neighbor, component)

    while stack:
        node = stack.pop()
        if node not in visited:
            component = set()
            dfs2(node, component)
            if component:
                sccs.append(component)

    return sccs
