def kmp_search(text, pattern):
    """
    Find all starting indices where pattern occurs in text using KMP algorithm.
    Returns list of indices (0-based).
    """
    if not pattern:
        return list(range(len(text) + 1))

    # Build KMP failure function (partial match indicator)
    def build_failure():
        m = len(pattern)
        failure = [0] * m
        j = 0

        for i in range(1, m):
            while j > 0 and pattern[i] != pattern[j]:
                j = failure[j - 1]
            if pattern[i] == pattern[j]:
                j += 1
            failure[i] = j

        return failure

    failure = build_failure()
    n, m = len(text), len(pattern)
    indices = []

    j = 0  # pattern index

    for i in range(n):
        while j > 0 and text[i] != pattern[j]:
            j = failure[j - 1]

        if text[i] == pattern[j]:
            j += 1

        # Pattern found at position i - j + 1
        if j == m:
            indices.append(i - m + 1)
            j = failure[j - 1] if j > 0 else 0

    return indices

