class MinMaxStack {
  private stack: number[] = [];
  private minStack: number[] = [];
  private maxStack: number[] = [];

  push(val: number): void {
    this.stack.push(val);
    if (this.minStack.length === 0 || val <= this.minStack[this.minStack.length - 1]) {
      this.minStack.push(val);
    }
    if (this.maxStack.length === 0 || val >= this.maxStack[this.maxStack.length - 1]) {
      this.maxStack.push(val);
    }
  }

  pop(): number {
    if (this.stack.length === 0) throw new Error("Stack is empty");
    const val = this.stack.pop()!;
    if (val === this.minStack[this.minStack.length - 1]) {
      this.minStack.pop();
    }
    if (val === this.maxStack[this.maxStack.length - 1]) {
      this.maxStack.pop();
    }
    return val;
  }

  top(): number {
    if (this.stack.length === 0) throw new Error("Stack is empty");
    return this.stack[this.stack.length - 1];
  }

  get_min(): number {
    if (this.minStack.length === 0) throw new Error("Stack is empty");
    return this.minStack[this.minStack.length - 1];
  }

  get_max(): number {
    if (this.maxStack.length === 0) throw new Error("Stack is empty");
    return this.maxStack[this.maxStack.length - 1];
  }
}
```

