def next_permutation(nums):
    # Step 1: Find the longest non-increasing suffix
    pivot = -1
    for i in range(len(nums) - 2, -1, -1):
        if nums[i] < nums[i + 1]:
            pivot = i
            break
    # If no pivot exists, this is the largest permutation; return sorted
    if pivot == -1:
        nums.reverse()
        return nums

    # Step 2: Find the smallest number larger than nums[pivot] in the suffix
    for i in range(len(nums) - 1, pivot, -1):
        if nums[i] > nums[pivot]:
            nums[i], nums[pivot] = nums[pivot], nums[i]
            break

    # Step 3: Reverse the suffix to get the next lexicographic order
    nums[pivot + 1:] = reversed(nums[pivot + 1:])
    return nums

