import math

def trap_rainwater(heights):
    if len(heights) < 3:
        return 0
    left = [0] * len(heights)
    right = [0] * len(heights)
    left[0] = heights[0]
    right[-1] = heights[-1]
    for i in range(1, len(heights)):
        left[i] = max(left[i-1], heights[i])
    for i in range(len(heights)-2, 0, -1):
        right[i] = max(right[i+1], heights[i])
    total = 0
    for i in range(len(heights)):
        total += min(left[i], right[i]) - heights[i]
    return total

