def calculate_expression(expression: str) -> int:
    """
    Evaluates a mathematical expression string containing integers, +, -, *, /,
    parentheses, and spaces. Division truncates toward zero. Respects operator
    precedence.
    """
    def tokenize(expr: str) -> list[str]:
        # Remove spaces and split by non-digit, non-operator characters
        return re.findall(r'\d+|\+|\-|\*|\/|\(|\)', expr.replace(' ', ''))

    def evaluate(tokens: list[str]) -> int:
        # Remove parentheses and evaluate innermost expressions recursively
        stack = []
        for token in tokens:
            if token == '(':
                stack.append('(')
            elif token == ')':
                # Pop until matching (
                result = 0
                neg = False
                while stack and stack[-1] != '(':
                    op = stack.pop()
                    if op == '-':
                        neg = True
                    elif op == '+':
                        result += int(stack.pop())
                    elif op == '*':
                        result *= int(stack.pop())
                    elif op == '/':
                        last = int(stack.pop())
                        result = int(result / last) if last != 0 else 0
                stack.pop()  # Remove (
                if neg:
                    result = -result
                stack.append(str(result))
            else:
                stack.append(token)

        # Evaluate remaining tokens from left to right with precedence
        result = 0
        neg = False
        while stack:
            token = stack.pop()
            if token == '+':
                result += int(stack.pop()) if stack else 0
            elif token == '-':
                neg = True
                result -= int(stack.pop()) if stack else 0
            elif token == '*':
                last = int(stack.pop())
                result *= last
            elif token == '/':
                last = int(stack.pop())
                if last != 0:
                    result = int(result / last)
                else:
                    result = 0
            else:
                stack.append(token)

        return result if not neg else -result

    tokens = tokenize(expression)
    return evaluate(tokens)
