def maximal_rectangle(matrix: List[List[str]]) -> int:
    if not matrix or not matrix[0]:
        return 0

    rows, cols = len(matrix), len(matrix[0])
    heights = [0] * cols
    max_area = 0

    for row in matrix:
        for col in range(cols):
            heights[col] = heights[col] + 1 if row[col] == '1' else 0
        area = largest_rectangle_in_histogram(heights)
        max_area = max(max_area, area)

    return max_area


def largest_rectangle_in_histogram(heights: List[int]) -> int:
    stack = []
    max_area = 0
    for h in heights:
        while stack and stack[-1][1] >= h:
            width = stack.pop()[0]
            max_area = max(max_area, width * h)
        stack.append([width + 1, h])
    while stack:
        width = stack.pop()[0]
        max_area = max(max_area, width * stack[-1][1] if stack else 0)
    return max_area

def matrix_exponentiation(n):
    MOD = 10**9 + 7

    def mat_mult(a, b):
        return [
            [(a[i][k] * b[k][j]) % MOD for j in range(2)] for i in range(2)
        ]

    def mat_pow(matrix, power):
        result = [[1, 0], [0, 1]]  # identity matrix
        base = matrix

        while power > 0:
            if power & 1:
                result = mat_mult(result, base)
            base = mat_mult(base, base)
            power >>= 1

        return result

    if n == 0:
        return 0
    if n == 1:
        return 1

    # Fibonacci transformation matrix [[1,1],[1,0]]
    fib_matrix = [[1, 1], [1, 0]]
    result_matrix = mat_pow(fib_matrix, n)

    # F(n) = result_matrix[0][0] * F(1) + result_matrix[0][1] * F(0)
    # F(n) = result_matrix[0][0] * 1 + result_matrix[0][1] * 0
    return result_matrix[0][0]

def matrix_chain_order(dimensions):
    n = len(dimensions) - 1
    m = [[0] * (n + 1) for _ in range(n + 1)]

    for length in range(2, n + 1):
        for i in range(1, n - length + 2):
            j = i + length - 1
            m[i][j] = float('inf')
            for k in range(i, j):
                cost = m[i][k] + m[k+1][j] + dimensions[i-1] * dimensions[k] * dimensions[j]
                m[i][j] = min(m[i][j], cost)
    return m[1][n]

