import random

class SkipList:
    def __init__(self, max_level=16, p=0.5):
        self.max_level = max_level
        self.p = p
        self.head = {}
        self.level = 1
        self._build_head()

    def _build_head(self):
        # Build a multi-level head node with all levels initialized to None
        self.head = {level: None for level in range(self.max_level)}

    def _random_level(self):
        # Generate random level with probability p at each level
        level = 1
        while random.random() < self.p and level < self.max_level:
            level += 1
        return level

    def insert(self, val):
        # Insert a new node with random level and maintain order
        new_node = {level: None for level in range(self.max_level)}
        new_node[self.level - 1] = val

        # Traverse from head to find insertion point
        current = self.head
        for level in range(self.level - 1, -1, -1):
            while current[level] is not None and current[level] < val:
                current = current[level]
            new_node[level] = current[level]

        # Insert at the correct position
        for level in range(self.level - 1, -1, -1):
            new_node[level] = val

        return True

    def search(self, val):
        # Search for a value using the multi-level structure
        current = self.head
        for level in range(self.level - 1, -1, -1):
            while current[level] is not None and current[level] < val:
                current = current[level]
        return current[0] == val

    def delete(self, val):
        # Delete a node and maintain the skip list structure
        current = self.head
        for level in range(self.level - 1, -1, -1):
            while current[level] is not None and current[level] < val:
                current = current[level]
        if current[0] == val:
            # Node found, delete it from all levels
            for level in range(self.level - 1, -1, -1):
                current[level] = None
            return True
        return False
```

This implementation features:

1. **Multi-level head structure** - each level points to the next level's head
2. **Random level generation** - uses the probability p to determine the level of each node
3. **O(log n) expected operations** - the multi-level structure provides logarithmic search and insert times
4. **Memory efficiency** - nodes are only allocated when needed

The skip list maintains its probabilistic nature with the p parameter controlling the trade-off between memory usage and lookup speed.

